{
  "verdict": "request_changes",
  "summary": "candidate.unique_by returns the last item for each key instead of the first, violating the specification.",
  "findings": [
    {
      "finding_id": "CAND-001",
      "file": "candidate.py",
      "line_start": 2,
      "line_end": 2,
      "severity": "high",
      "description": "The implementation uses a dict comprehension which replaces earlier items with later ones for duplicate keys, resulting in the last item being returned for each key. The specification requires returning the first item for each distinct key.",
      "evidence": ">>> unique_by([{'id':1,'v':'a'},{'id':1,'v':'b'}], lambda x: x['id'])\n# Current implementation returns [{'id':1,'v':'b'}], but the correct result should be [{'id':1,'v':'a'}]."
    }
  ]
}
